'use strict';

const { SerialPort } = require('serialport');
const {
  buildAbsoluteMousePayload,
  buildKeyboardPacketData,
  buildMouseClickPayload,
  buildRelativeMousePayload,
  CMD_GET_INFO,
  CMD_SEND_KB_GENERAL_DATA,
  CMD_SEND_MS_ABS_DATA,
  CMD_SEND_MS_REL_DATA,
  buildCmdPacket
} = require('./lib/protocol');
const {
  getKeyCode,
  getModifierMask,
  isModifierKey
} = require('./lib/keycodes');
const wyhkm = require('./lib/wyhkm-input');
const atoms3u = require('./lib/atoms3u-input');

const DEFAULT_OPTIONS = {
  portPath: '',
  baudRate: 57600,
  probeTimeoutMs: 1000,
  tolerancePx: 2,
  maxStepPx: 25,
  stepDelayMs: 8,
  moveTimeoutMs: 1500,
  stallThreshold: 5,
  logger: console
};

const DEFAULT_CH9329_OPTIONS = {
  ...DEFAULT_OPTIONS,
  baudRate: 9600,
  stepDelayMs: 20,
  waitForAck: true,
  commandResponseTimeoutMs: 200,
  logger: console
};

const RESPONSE_GET_INFO = 0x81;
const INPUT_DEVICE_KINDS = new Set(['wyhkm', 'atoms3u', 'nanokvm', 'ch9329']);
const DEFAULT_SERIAL_INPUT_KIND_ORDER = ['atoms3u', 'ch9329', 'nanokvm'];
const DEFAULT_INPUT_KIND_ORDER_WIN32 = ['wyhkm', 'atoms3u', 'ch9329', 'nanokvm'];
const DEFAULT_INPUT_KIND_ORDER = process.platform === 'win32'
  ? DEFAULT_INPUT_KIND_ORDER_WIN32
  : DEFAULT_SERIAL_INPUT_KIND_ORDER;
const KNOWN_NANOKVM_VENDOR_IDS = new Set([
  '1a86', // QinHeng CH34x / CH910x
  '10c4', // Silicon Labs CP210x
  '0403', // FTDI
  '2e8a', // Raspberry Pi / RP2040 USB serial
  '303a' // Espressif USB serial / JTAG
]);

const NANOKVM_TEXT_PATTERNS = [
  /nanokvm/i,
  /\bkvm\b/i,
  /sipeed/i,
  /lichee/i,
  /maix/i,
  /ch34/i,
  /ch91/i,
  /wch/i,
  /cp210/i,
  /ftdi/i,
  /usb[-\s]?serial/i,
  /usb[-\s]?uart/i,
  /serial/i,
  /modem/i,
  /rp2040/i
];

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function normalizeButton(button) {
  if (button === 'right') return 2;
  if (button === 'middle') return 4;
  return 1;
}

function normalizeClickOptions(value = {}) {
  const options = value && typeof value === 'object' ? value : {};
  const holdMs = Number(options.holdMs);
  const repeat = Number(options.repeat);
  const intervalMs = Number(options.intervalMs);
  const nudgePx = Number(options.nudgePx);

  return {
    holdMs: Number.isFinite(holdMs) && holdMs >= 0
      ? Math.round(holdMs)
      : 60 + Math.round(Math.random() * 60),
    repeat: Number.isFinite(repeat) && repeat > 0
      ? Math.max(1, Math.round(repeat))
      : 1,
    intervalMs: Number.isFinite(intervalMs) && intervalMs >= 0
      ? Math.round(intervalMs)
      : 30 + Math.round(Math.random() * 40),
    nudgePx: Number.isFinite(nudgePx)
      ? clamp(Math.round(nudgePx), -127, 127)
      : 0
  };
}

function normalizePlatform(platform) {
  return platform === 'darwin' ? 'darwin' : 'win32';
}

function normalizeInputDeviceKind(kind) {
  return INPUT_DEVICE_KINDS.has(kind) ? kind : '';
}

function getDefaultBaudRateForKind(kind) {
  if (kind === 'wyhkm') return undefined;
  if (kind === 'atoms3u') return 115200;
  return kind === 'ch9329' ? DEFAULT_CH9329_OPTIONS.baudRate : DEFAULT_OPTIONS.baudRate;
}

function inferInputDeviceKindFromBaudRate(baudRate) {
  if (Number(baudRate) === DEFAULT_CH9329_OPTIONS.baudRate) {
    return 'ch9329';
  }
  if (Number(baudRate) === DEFAULT_OPTIONS.baudRate) {
    return 'nanokvm';
  }
  return '';
}

function normalizeInputKindOrder(value) {
  const source = Array.isArray(value) && value.length > 0 ? value : DEFAULT_INPUT_KIND_ORDER;
  const seen = new Set();
  const order = [];

  for (const item of source) {
    const kind = normalizeInputDeviceKind(item);
    if (kind && !seen.has(kind)) {
      seen.add(kind);
      order.push(kind);
    }
  }

  return order.length > 0 ? order : DEFAULT_INPUT_KIND_ORDER;
}

function getInputProbePlans(options = {}) {
  const configuredKind = normalizeInputDeviceKind(options.kind || options.deviceKind);
  const configuredBaudRate = Number(options.baudRate);

  if (configuredKind) {
    return [{
      kind: configuredKind,
      baudRate: Number.isFinite(configuredBaudRate) && configuredBaudRate > 0
        ? configuredBaudRate
        : getDefaultBaudRateForKind(configuredKind)
    }];
  }

  if (Number.isFinite(configuredBaudRate) && configuredBaudRate > 0) {
    return [{
      kind: inferInputDeviceKindFromBaudRate(configuredBaudRate) || 'nanokvm',
      baudRate: configuredBaudRate
    }];
  }

  return normalizeInputKindOrder(options.preferredKinds).map((kind) => ({
    kind,
    baudRate: getDefaultBaudRateForKind(kind)
  }));
}

function buildRelativeStep(dx, dy, options) {
  const activeX = Math.abs(dx) > options.tolerancePx;
  const activeY = Math.abs(dy) > options.tolerancePx;

  if (!activeX && !activeY) {
    return { x: 0, y: 0 };
  }

  const maxStep = Number.isFinite(options.maxStepPx) && options.maxStepPx > 0
    ? options.maxStepPx
    : 1;
  let stepX = activeX ? clamp(Math.round(dx), -maxStep, maxStep) : 0;
  let stepY = activeY ? clamp(Math.round(dy), -maxStep, maxStep) : 0;

  if (stepX === 0 && activeX) {
    stepX = dx > 0 ? 1 : -1;
  }
  if (stepY === 0 && activeY) {
    stepY = dy > 0 ? 1 : -1;
  }

  return { x: stepX, y: stepY };
}

function emitMoveStep(options, event) {
  if (typeof options.onMoveStep !== 'function') {
    return;
  }

  try {
    options.onMoveStep(event);
  } catch (error) {
    callLogger(options.logger, 'warn', '[moveTo] onMoveStep failed:', error);
  }
}

function callLogger(logger, level, ...args) {
  const fn = logger && typeof logger[level] === 'function' ? logger[level] : null;
  if (fn) {
    fn(...args);
  }
}

async function closeSerialPort(serialPortInstance) {
  if (!serialPortInstance || !serialPortInstance.isOpen) {
    return;
  }

  await new Promise((resolve) => {
    serialPortInstance.close(() => resolve());
  });
}

function normalizeUsbId(value) {
  return String(value || '').trim().toLowerCase().replace(/^0x/, '');
}

function deviceSearchText(device) {
  return [
    device.path,
    device.manufacturer,
    device.serialNumber,
    device.vendorId,
    device.productId,
    device.friendlyName
  ]
    .filter(Boolean)
    .join(' ');
}

function looksLikeNanoKvmDevice(device) {
  const vendorId = normalizeUsbId(device.vendorId);
  const text = deviceSearchText(device);

  if (/nanokvm/i.test(text)) {
    return true;
  }

  if (KNOWN_NANOKVM_VENDOR_IDS.has(vendorId)) {
    return true;
  }

  return NANOKVM_TEXT_PATTERNS.some((pattern) => pattern.test(text)) || Boolean(device.isUsbLike);
}

function inferSerialDeviceKind(port) {
  const text = deviceSearchText(port);
  if (/ch9329|ch9328|ch93/i.test(text)) {
    return 'ch9329';
  }
  if (/nanokvm|\bkvm\b|sipeed|lichee|maix/i.test(text)) {
    return 'nanokvm';
  }
  return '';
}

async function listSerialDevices() {
  const ports = await SerialPort.list();
  return ports.map((port) => ({
    path: port.path,
    portPath: port.path,
    kind: inferSerialDeviceKind(port) || undefined,
    supportedKinds: ['ch9329', 'nanokvm'],
    manufacturer: port.manufacturer || '',
    serialNumber: port.serialNumber || '',
    vendorId: port.vendorId || '',
    productId: port.productId || '',
    friendlyName: port.friendlyName || port.path,
    isUsbLike:
      /usb/i.test(port.path || '') ||
      /usb/i.test(port.manufacturer || '') ||
      /wch|ch34|serial/i.test(port.friendlyName || '')
  }));
}

async function listDevices(options = {}) {
  const configuredKind = normalizeInputDeviceKind(options.kind || options.deviceKind);
  const deviceGroups = await Promise.all([
    configuredKind && configuredKind !== 'wyhkm'
      ? Promise.resolve([])
      : wyhkm.listDevices(options).catch(() => []),
    configuredKind && configuredKind !== 'atoms3u'
      ? Promise.resolve([])
      : atoms3u.detectAtomS3UDevices(options).catch(() => [])
  ]);
  return deviceGroups.flat();
}

async function detectNanoKvmDevices() {
  const devices = await listSerialDevices();
  return devices.filter(looksLikeNanoKvmDevice);
}

function createReasonFromError(error) {
  return error?.message || String(error || 'Unknown NanoKVM probe error');
}

function isValidPacket(packet) {
  if (!packet || packet.length < 6 || packet[0] !== 0x57 || packet[1] !== 0xab) {
    return false;
  }

  const length = packet[4];
  if (packet.length < 6 + length) {
    return false;
  }

  let sum = 0;
  for (let index = 0; index < 5 + length; index += 1) {
    sum += packet[index];
  }

  return (sum & 0xff) === packet[5 + length];
}

function readPacketFromBuffer(buffer) {
  for (let index = 0; index <= buffer.length - 6; index += 1) {
    if (buffer[index] !== 0x57 || buffer[index + 1] !== 0xab) {
      continue;
    }

    const length = buffer[index + 4];
    const end = index + 6 + length;
    if (buffer.length < end) {
      return null;
    }

    const packet = buffer.slice(index, end);
    if (isValidPacket(packet)) {
      return {
        packet,
        nextBuffer: buffer.slice(end)
      };
    }
  }

  return null;
}

function waitForInfoResponse(serialPortInstance, timeoutMs) {
  return new Promise((resolve, reject) => {
    let buffer = Buffer.alloc(0);
    let settled = false;

    function cleanup() {
      serialPortInstance.off('data', onData);
      serialPortInstance.off('error', onError);
      clearTimeout(timer);
    }

    function settle(fn, value) {
      if (settled) {
        return;
      }
      settled = true;
      cleanup();
      fn(value);
    }

    function handlePacket(packet) {
      if (packet[3] !== RESPONSE_GET_INFO) {
        return;
      }

      const length = packet[4];
      const payload = packet.slice(5, 5 + length);
      const mounted = payload.length < 2 || payload[1] !== 0;

      if (!mounted) {
        settle(reject, new Error('NanoKVM responded but HID mount is not ready'));
        return;
      }

      settle(resolve, {
        command: packet[3],
        payload
      });
    }

    function onData(data) {
      buffer = Buffer.concat([buffer, data]);

      while (buffer.length >= 6) {
        const result = readPacketFromBuffer(buffer);
        if (!result) {
          break;
        }
        buffer = result.nextBuffer;
        handlePacket(result.packet);
        if (settled) {
          break;
        }
      }
    }

    function onError(error) {
      settle(reject, error);
    }

    const timer = setTimeout(() => {
      settle(reject, new Error('Timed out waiting for NanoKVM info response'));
    }, timeoutMs);

    serialPortInstance.on('data', onData);
    serialPortInstance.on('error', onError);
  });
}

function waitForCommandResponse(serialPortInstance, command, timeoutMs) {
  return new Promise((resolve, reject) => {
    let buffer = Buffer.alloc(0);
    let settled = false;
    const okCommand = command | 0x80;
    const errorCommand = command | 0xc0;

    function cleanup() {
      serialPortInstance.off('data', onData);
      serialPortInstance.off('error', onError);
      clearTimeout(timer);
    }

    function settle(fn, value) {
      if (settled) {
        return;
      }
      settled = true;
      cleanup();
      fn(value);
    }

    function handlePacket(packet) {
      if (packet[3] === errorCommand) {
        settle(reject, new Error(`CH9329 command 0x${command.toString(16)} returned an error response`));
        return;
      }

      if (packet[3] !== okCommand) {
        return;
      }

      const length = packet[4];
      settle(resolve, {
        command: packet[3],
        payload: packet.slice(5, 5 + length)
      });
    }

    function onData(data) {
      buffer = Buffer.concat([buffer, data]);

      while (buffer.length >= 6) {
        const result = readPacketFromBuffer(buffer);
        if (!result) {
          break;
        }
        buffer = result.nextBuffer;
        handlePacket(result.packet);
        if (settled) {
          break;
        }
      }
    }

    function onError(error) {
      settle(reject, error);
    }

    const timer = setTimeout(() => {
      settle(reject, new Error(`Timed out waiting for CH9329 command 0x${command.toString(16)} response`));
    }, timeoutMs);

    serialPortInstance.on('data', onData);
    serialPortInstance.on('error', onError);
  });
}

async function writePacketToSerialPort(serialPortInstance, packet) {
  await new Promise((resolve, reject) => {
    serialPortInstance.write(packet, (error) => {
      if (error) {
        reject(error);
        return;
      }
      serialPortInstance.drain((drainError) => {
        if (drainError) reject(drainError);
        else resolve();
      });
    });
  });
}

async function probeNanoKvmDevice(portPath, options = {}) {
  if (!portPath || typeof portPath !== 'string') {
    return {
      available: false,
      portPath: portPath || '',
      reason: 'NanoKVM portPath is required'
    };
  }

  const devices = await listSerialDevices();
  const device = devices.find((item) => item.path === portPath);
  const probeOptions = {
    ...DEFAULT_OPTIONS,
    ...options,
    portPath,
    logger: Object.prototype.hasOwnProperty.call(options, 'logger') ? options.logger : null
  };
  const serialPortInstance = new SerialPort({
    path: portPath,
    baudRate: probeOptions.baudRate,
    autoOpen: false
  });

  try {
    await new Promise((resolve, reject) => {
      serialPortInstance.open((error) => {
        if (error) {
          reject(error);
          return;
        }
        resolve();
      });
    });
    const responsePromise = waitForInfoResponse(serialPortInstance, probeOptions.probeTimeoutMs);
    await writePacketToSerialPort(serialPortInstance, buildCmdPacket(CMD_GET_INFO, []));
    await responsePromise;
    await closeSerialPort(serialPortInstance);
    return {
      available: true,
      portPath,
      device
    };
  } catch (error) {
    try {
      await closeSerialPort(serialPortInstance);
    } catch {
      // Ignore cleanup errors after a failed probe.
    }

    return {
      available: false,
      portPath,
      device,
      reason: createReasonFromError(error)
    };
  }
}

async function autoDetectNanoKvm(options = {}) {
  const candidates = await detectNanoKvmDevices();
  if (candidates.length === 0) {
    return {
      available: false,
      candidates,
      reason: 'No NanoKVM-like serial devices found'
    };
  }

  const failedReasons = [];

  for (const candidate of candidates) {
    const result = await probeNanoKvmDevice(candidate.path, options);
    if (result.available) {
      return {
        available: true,
        portPath: result.portPath,
        device: result.device || candidate,
        candidates
      };
    }

    failedReasons.push(`${candidate.path}: ${result.reason || 'probe failed'}`);
  }

  return {
    available: false,
    candidates,
    reason: failedReasons.length > 0
      ? `No available NanoKVM device found (${failedReasons.join('; ')})`
      : 'No available NanoKVM device found'
  };
}

async function probeInputDevice(portPath, options = {}) {
  const configuredKind = normalizeInputDeviceKind(options.kind || options.deviceKind);
  if (configuredKind === 'wyhkm') {
    return wyhkm.probeWyHkmDevice(
      typeof portPath === 'number' ? portPath : Number(portPath),
      options
    );
  }

  if (configuredKind === 'atoms3u') {
    return atoms3u.probeAtomS3UDevice(String(portPath || ''), options);
  }

  if (!portPath || typeof portPath !== 'string') {
    return {
      available: false,
      portPath: portPath || '',
      reason: 'Input device portPath is required'
    };
  }

  const plans = getInputProbePlans(options);
  const failedReasons = [];

  for (const plan of plans) {
    if (plan.kind === 'wyhkm') {
      continue;
    }

    if (plan.kind === 'atoms3u') {
      const result = await atoms3u.probeAtomS3UDevice(portPath, options);
      if (result.available) {
        return result;
      }
      failedReasons.push(`atoms3u@${getDefaultBaudRateForKind('atoms3u')}: ${result.reason || 'probe failed'}`);
      continue;
    }

    const result = await probeNanoKvmDevice(portPath, {
      ...options,
      baudRate: plan.baudRate
    });

    if (result.available) {
      return {
        ...result,
        kind: plan.kind,
        baudRate: plan.baudRate
      };
    }

    failedReasons.push(`${plan.kind}@${plan.baudRate}: ${result.reason || 'probe failed'}`);
  }

  const devices = await listSerialDevices();
  const device = devices.find((item) => item.path === portPath);
  return {
    available: false,
    portPath,
    device,
    reason: failedReasons.length > 0
      ? `No available input device found (${failedReasons.join('; ')})`
      : 'No available input device found'
  };
}

async function autoDetectInputDevice(options = {}) {
  if (options.portPath) {
    return probeInputDevice(options.portPath, options);
  }

  const allCandidates = await listDevices(options);
  const configuredKind = normalizeInputDeviceKind(options.kind || options.deviceKind);
  const order = configuredKind ? [configuredKind] : normalizeInputKindOrder(options.preferredKinds);
  const failedReasons = [];

  if (order.includes('wyhkm')) {
    const result = await wyhkm.autoDetectWyHkm(options);
    if (result.available) {
      return {
        ...result,
        candidates: allCandidates
      };
    }
    failedReasons.push(`wyhkm: ${result.reason || 'probe failed'}`);
    if (configuredKind === 'wyhkm') {
      return {
        ...result,
        candidates: allCandidates
      };
    }
  }

  const devices = allCandidates.filter((device) => device.kind !== 'wyhkm');
  const candidates = devices.filter((device) => device.isUsbLike);
  const probeCandidates = candidates.length > 0 ? candidates : devices;

  if (probeCandidates.length === 0) {
    return {
      available: false,
      candidates: [],
      reason: failedReasons.length > 0
        ? `No available input device found (${failedReasons.join('; ')})`
        : 'No input devices found'
    };
  }

  for (const candidate of probeCandidates) {
    const result = await probeInputDevice(candidate.path, {
      ...options,
      preferredKinds: order.filter((kind) => kind !== 'wyhkm')
    });
    if (result.available) {
      return {
        available: true,
        kind: result.kind,
        baudRate: result.baudRate,
        portPath: result.portPath,
        device: result.device || candidate,
        candidates: allCandidates
      };
    }

    failedReasons.push(`${candidate.path}: ${result.reason || 'probe failed'}`);
  }

  return {
    available: false,
    candidates: allCandidates,
    reason: failedReasons.length > 0
      ? `No available input device found (${failedReasons.join('; ')})`
      : 'No available input device found'
  };
}

function createInputFromDetectedDevice(detection, options = {}) {
  if (!detection?.available || !detection?.portPath) {
    throw new Error(detection?.reason || 'No available input device detected');
  }

  const kind = normalizeInputDeviceKind(detection.kind);
  if (kind === 'wyhkm') {
    return wyhkm.createInputFromDetectedDevice(detection, options);
  }

  if (kind === 'atoms3u') {
    return atoms3u.createInputFromDetectedDevice(detection, options);
  }

  const inputOptions = {
    ...options,
    portPath: detection.portPath,
    baudRate: detection.baudRate || options.baudRate || getDefaultBaudRateForKind(kind)
  };

  if (kind === 'ch9329') {
    return createCh9329Input(inputOptions);
  }

  return createNanoKvmInput(inputOptions);
}

async function createInputFromAutoDetect(options = {}) {
  const detection = await autoDetectInputDevice(options);
  return {
    detection,
    input: createInputFromDetectedDevice(detection, options)
  };
}

function pickDefaultDevice(devices) {
  const serialDevices = devices.filter((device) => device.kind !== 'wyhkm');
  return serialDevices.find((device) => device.isUsbLike) || serialDevices[0] || null;
}

function createNanoKvmInput(userOptions = {}) {
  const options = { ...DEFAULT_OPTIONS, ...userOptions };
  const logger = options.logger || console;

  let port = null;
  let connected = false;
  let lastError = '';
  let currentPath = options.portPath || '';
  let pressedModifierMask = 0;
  const pressedKeyCodes = new Set();

  function resetKeyState() {
    pressedModifierMask = 0;
    pressedKeyCodes.clear();
  }

  async function writePacket(packet) {
    if (!port || !connected) {
      throw new Error('NanoKVM is not connected');
    }

    await new Promise((resolve, reject) => {
      port.write(packet, (error) => {
        if (error) {
          reject(error);
          return;
        }
        port.drain((drainError) => {
          if (drainError) reject(drainError);
          else resolve();
        });
      });
    });
  }

  async function sendCommand(command, payload) {
    const responsePromise = options.waitForAck
      ? waitForCommandResponse(port, command, options.commandResponseTimeoutMs)
      : null;
    await writePacket(buildCmdPacket(command, payload));
    if (responsePromise) {
      await responsePromise;
    }
  }

  async function ensurePortPath() {
    if (currentPath) {
      return currentPath;
    }

    const devices = await listSerialDevices();
    const picked = pickDefaultDevice(devices);
    if (!picked) {
      throw new Error('No serial devices found for NanoKVM');
    }
    currentPath = picked.path;
    return currentPath;
  }

  function bindPortEvents(serialPortInstance) {
    serialPortInstance.on('error', (error) => {
      connected = false;
      lastError = error?.message || String(error);
      callLogger(logger, 'error', '[NanoKVM] serial error:', error);
    });

    serialPortInstance.on('close', () => {
      connected = false;
      callLogger(logger, 'warn', '[NanoKVM] serial port closed');
    });
  }

  async function connect() {
    if (port && connected) {
      return;
    }

    const path = await ensurePortPath();
    lastError = '';

    const serialPortInstance = new SerialPort({
      path,
      baudRate: options.baudRate,
      autoOpen: false
    });

    bindPortEvents(serialPortInstance);

    await new Promise((resolve, reject) => {
      serialPortInstance.open((error) => {
        if (error) {
          reject(error);
          return;
        }
        resolve();
      });
    });

    port = serialPortInstance;
    connected = true;

    try {
      await sendCommand(CMD_GET_INFO, []);
    } catch (error) {
      lastError = error?.message || String(error);
      connected = false;
      port = null;
      await new Promise((resolve) => {
        serialPortInstance.close(() => resolve());
      });
      throw error;
    }
  }

  async function disconnect() {
    resetKeyState();

    if (!port) {
      connected = false;
      return;
    }

    const currentPort = port;
    port = null;
    connected = false;

    await new Promise((resolve) => {
      currentPort.close(() => resolve());
    });
  }

  async function getHealth() {
    return {
      connected,
      portPath: currentPath || undefined,
      reason: connected ? undefined : lastError || 'NanoKVM not connected'
    };
  }

  async function sendRelativeMove(dx, dy, buttons = 0) {
    await connect();

    const boundedX = clamp(Math.round(dx), -127, 127);
    const boundedY = clamp(Math.round(dy), -127, 127);

    await sendCommand(CMD_SEND_MS_REL_DATA, buildRelativeMousePayload(buttons, boundedX, boundedY, 0));
  }

  async function moveTo(targetX, targetY, getCursorPos) {
    if (typeof getCursorPos !== 'function') {
      throw new Error('moveTo requires a getCursorPos callback');
    }

    await connect();

    const startAt = Date.now();
    let previousDistance = Number.POSITIVE_INFINITY;
    let stallCount = 0;
    let iteration = 0;

    while (Date.now() - startAt <= options.moveTimeoutMs) {
      const point = await Promise.resolve(getCursorPos());
      if (!point || typeof point.x !== 'number' || typeof point.y !== 'number') {
        throw new Error('getCursorPos must return { x, y }');
      }

      const dx = targetX - point.x;
      const dy = targetY - point.y;

      if (Math.abs(dx) <= options.tolerancePx && Math.abs(dy) <= options.tolerancePx) {
        emitMoveStep(options, {
          device: 'nanokvm',
          phase: 'done',
          iteration,
          elapsedMs: Date.now() - startAt,
          target: { x: targetX, y: targetY },
          point: { x: point.x, y: point.y },
          delta: { dx, dy },
          tolerancePx: options.tolerancePx
        });
        return;
      }

      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance >= previousDistance - 0.25) {
        stallCount += 1;
      } else {
        stallCount = 0;
      }

      if (stallCount >= options.stallThreshold) {
        throw new Error('NanoKVM relative movement stalled before reaching target');
      }

      previousDistance = distance;

      const step = buildRelativeStep(dx, dy, options);
      emitMoveStep(options, {
        device: 'nanokvm',
        phase: 'step',
        iteration,
        elapsedMs: Date.now() - startAt,
        target: { x: targetX, y: targetY },
        point: { x: point.x, y: point.y },
        delta: { dx, dy },
        distance,
        step,
        stallCount,
        tolerancePx: options.tolerancePx,
        stepDelayMs: options.stepDelayMs
      });

      await sendRelativeMove(step.x, step.y);
      await sleep(options.stepDelayMs);
      iteration += 1;
    }

    emitMoveStep(options, {
      device: 'nanokvm',
      phase: 'timeout',
      iteration,
      elapsedMs: Date.now() - startAt,
      target: { x: targetX, y: targetY }
    });
    throw new Error('NanoKVM moveTo timed out');
  }

  async function click(button = 'left', clickOptions = {}) {
    await connect();

    const buttonMask = normalizeButton(button);
    const normalizedClickOptions = normalizeClickOptions(clickOptions);
    for (let index = 0; index < normalizedClickOptions.repeat; index += 1) {
      if (normalizedClickOptions.nudgePx) {
        await sendCommand(
          CMD_SEND_MS_REL_DATA,
          buildRelativeMousePayload(buttonMask, normalizedClickOptions.nudgePx, 0, 0)
        );
      } else {
        await sendCommand(CMD_SEND_MS_REL_DATA, buildMouseClickPayload(buttonMask));
      }
      await sleep(normalizedClickOptions.holdMs);
      if (normalizedClickOptions.nudgePx) {
        await sendCommand(
          CMD_SEND_MS_REL_DATA,
          buildRelativeMousePayload(0, -normalizedClickOptions.nudgePx, 0, 0)
        );
      } else {
        await sendCommand(CMD_SEND_MS_REL_DATA, buildMouseClickPayload(0));
      }
      if (index < normalizedClickOptions.repeat - 1) {
        await sleep(normalizedClickOptions.intervalMs);
      }
    }
    await sleep(normalizedClickOptions.intervalMs);
  }

  async function moveAndClick(targetX, targetY, getCursorPos, button = 'left') {
    await moveTo(targetX, targetY, getCursorPos);
    await click(button);
  }

  function getPressedKeyArray() {
    return Array.from(pressedKeyCodes).slice(0, 6);
  }

  async function syncKeyboardState() {
    await connect();
    await sendCommand(
      CMD_SEND_KB_GENERAL_DATA,
      buildKeyboardPacketData(pressedModifierMask, getPressedKeyArray())
    );
  }

  async function keyToggle(key, state) {
    const normalizedState = state === 'down' ? 'down' : 'up';
    const modifierMask = getModifierMask(key);
    const keyCode = getKeyCode(key);

    if (isModifierKey(key)) {
      if (normalizedState === 'down') {
        pressedModifierMask |= modifierMask;
      } else {
        pressedModifierMask &= ~modifierMask;
      }
      await syncKeyboardState();
      return;
    }

    if (!keyCode) {
      throw new Error(`Unsupported NanoKVM keyToggle key: ${key}`);
    }

    if (normalizedState === 'down') {
      pressedKeyCodes.add(keyCode);
    } else {
      pressedKeyCodes.delete(keyCode);
    }

    await syncKeyboardState();
  }

  async function keyTap(key, modifiers = []) {
    const keyCode = getKeyCode(key);
    if (!keyCode) {
      throw new Error(`Unsupported NanoKVM keyTap key: ${key}`);
    }

    const mask = modifiers.reduce((value, modifier) => value | getModifierMask(modifier), 0);
    await connect();
    await sendCommand(CMD_SEND_KB_GENERAL_DATA, buildKeyboardPacketData(mask, [keyCode]));
    await sleep(50);
    await sendCommand(CMD_SEND_KB_GENERAL_DATA, buildKeyboardPacketData(0, []));
  }

  async function pasteShortcut(platform) {
    const modifier = normalizePlatform(platform) === 'darwin' ? 'command' : 'control';
    await keyTap('v', [modifier]);
    await keyToggle(modifier, 'up');
  }

  return {
    connect,
    disconnect,
    listDevices: listSerialDevices,
    getHealth,
    moveTo,
    click,
    moveAndClick,
    keyTap,
    keyToggle,
    pasteShortcut,
    _debug: {
      sendRelativeMove
    }
  };
}

function createCh9329Input(userOptions = {}) {
  const options = { ...DEFAULT_CH9329_OPTIONS, ...userOptions };
  const logger = options.logger || console;

  let port = null;
  let connected = false;
  let lastError = '';
  let currentPath = options.portPath || '';
  let pressedModifierMask = 0;
  const pressedKeyCodes = new Set();

  function resetKeyState() {
    pressedModifierMask = 0;
    pressedKeyCodes.clear();
  }

  async function writePacket(packet) {
    if (!port || !connected) {
      throw new Error('CH9329 is not connected');
    }

    await new Promise((resolve, reject) => {
      port.write(packet, (error) => {
        if (error) {
          reject(error);
          return;
        }
        port.drain((drainError) => {
          if (drainError) reject(drainError);
          else resolve();
        });
      });
    });
  }

  async function sendCommand(command, payload) {
    const responsePromise = options.waitForAck
      ? waitForCommandResponse(port, command, options.commandResponseTimeoutMs)
      : null;
    await writePacket(buildCmdPacket(command, payload));
    if (responsePromise) {
      await responsePromise;
    }
  }

  async function ensurePortPath() {
    if (currentPath) {
      return currentPath;
    }

    const devices = await listSerialDevices();
    const picked = pickDefaultDevice(devices);
    if (!picked) {
      throw new Error('No serial devices found for CH9329');
    }
    currentPath = picked.path;
    return currentPath;
  }

  function bindPortEvents(serialPortInstance) {
    serialPortInstance.on('error', (error) => {
      connected = false;
      lastError = error?.message || String(error);
      callLogger(logger, 'error', '[CH9329] serial error:', error);
    });

    serialPortInstance.on('close', () => {
      connected = false;
      callLogger(logger, 'warn', '[CH9329] serial port closed');
    });
  }

  async function connect() {
    if (port && connected) {
      return;
    }

    const path = await ensurePortPath();
    lastError = '';

    const serialPortInstance = new SerialPort({
      path,
      baudRate: options.baudRate,
      autoOpen: false
    });

    bindPortEvents(serialPortInstance);

    await new Promise((resolve, reject) => {
      serialPortInstance.open((error) => {
        if (error) {
          reject(error);
          return;
        }
        resolve();
      });
    });

    port = serialPortInstance;
    connected = true;

    try {
      await sendCommand(CMD_GET_INFO, []);
    } catch (error) {
      lastError = error?.message || String(error);
      connected = false;
      port = null;
      await new Promise((resolve) => {
        serialPortInstance.close(() => resolve());
      });
      throw error;
    }
  }

  async function disconnect() {
    resetKeyState();

    if (!port) {
      connected = false;
      return;
    }

    const currentPort = port;
    port = null;
    connected = false;

    await new Promise((resolve) => {
      currentPort.close(() => resolve());
    });
  }

  async function getHealth() {
    return {
      connected,
      portPath: currentPath || undefined,
      reason: connected ? undefined : lastError || 'CH9329 not connected'
    };
  }

  async function sendAbsoluteMove(x, y, buttons = 0, wheel = 0, screenWidth, screenHeight) {
    await connect();
    const point = {
      x: Math.round(x),
      y: Math.round(y)
    };
    await sendCommand(
      CMD_SEND_MS_ABS_DATA,
      buildAbsoluteMousePayload(
        buttons,
        point.x,
        point.y,
        screenWidth || options.screenWidth,
        screenHeight || options.screenHeight,
        wheel
      )
    );
  }

  async function sendRelativeMove(dx, dy, buttons = 0) {
    await connect();

    const boundedX = clamp(Math.round(dx), -127, 127);
    const boundedY = clamp(Math.round(dy), -127, 127);

    await sendCommand(CMD_SEND_MS_REL_DATA, buildRelativeMousePayload(buttons, boundedX, boundedY, 0));
  }

  async function moveTo(targetX, targetY, getCursorPos) {
    if (typeof getCursorPos !== 'function') {
      throw new Error('CH9329 moveTo requires a getCursorPos callback');
    }

    await connect();

    const startAt = Date.now();
    let previousDistance = Number.POSITIVE_INFINITY;
    let stallCount = 0;
    let iteration = 0;

    while (Date.now() - startAt <= options.moveTimeoutMs) {
      const point = await Promise.resolve(getCursorPos());
      if (!point || typeof point.x !== 'number' || typeof point.y !== 'number') {
        throw new Error('getCursorPos must return { x, y }');
      }

      const dx = targetX - point.x;
      const dy = targetY - point.y;

      if (Math.abs(dx) <= options.tolerancePx && Math.abs(dy) <= options.tolerancePx) {
        emitMoveStep(options, {
          device: 'ch9329',
          phase: 'done',
          iteration,
          elapsedMs: Date.now() - startAt,
          target: { x: targetX, y: targetY },
          point: { x: point.x, y: point.y },
          delta: { dx, dy },
          tolerancePx: options.tolerancePx
        });
        return;
      }

      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance >= previousDistance - 0.25) {
        stallCount += 1;
      } else {
        stallCount = 0;
      }

      if (stallCount >= options.stallThreshold) {
        throw new Error('CH9329 relative movement stalled before reaching target');
      }

      previousDistance = distance;

      const step = buildRelativeStep(dx, dy, options);
      emitMoveStep(options, {
        device: 'ch9329',
        phase: 'step',
        iteration,
        elapsedMs: Date.now() - startAt,
        target: { x: targetX, y: targetY },
        point: { x: point.x, y: point.y },
        delta: { dx, dy },
        distance,
        step,
        stallCount,
        tolerancePx: options.tolerancePx,
        stepDelayMs: options.stepDelayMs
      });

      await sendRelativeMove(step.x, step.y);
      await sleep(options.stepDelayMs);
      iteration += 1;
    }

    emitMoveStep(options, {
      device: 'ch9329',
      phase: 'timeout',
      iteration,
      elapsedMs: Date.now() - startAt,
      target: { x: targetX, y: targetY }
    });
    throw new Error('CH9329 moveTo timed out');
  }

  async function click(button = 'left', clickOptions = {}) {
    await connect();

    const buttonMask = normalizeButton(button);
    const normalizedClickOptions = normalizeClickOptions(clickOptions);
    for (let index = 0; index < normalizedClickOptions.repeat; index += 1) {
      if (normalizedClickOptions.nudgePx) {
        await sendCommand(
          CMD_SEND_MS_REL_DATA,
          buildRelativeMousePayload(buttonMask, normalizedClickOptions.nudgePx, 0, 0)
        );
      } else {
        await sendCommand(CMD_SEND_MS_REL_DATA, buildMouseClickPayload(buttonMask));
      }
      await sleep(normalizedClickOptions.holdMs);
      if (normalizedClickOptions.nudgePx) {
        await sendCommand(
          CMD_SEND_MS_REL_DATA,
          buildRelativeMousePayload(0, -normalizedClickOptions.nudgePx, 0, 0)
        );
      } else {
        await sendCommand(CMD_SEND_MS_REL_DATA, buildMouseClickPayload(0));
      }
      if (index < normalizedClickOptions.repeat - 1) {
        await sleep(normalizedClickOptions.intervalMs);
      }
    }
    await sleep(normalizedClickOptions.intervalMs);
  }

  async function moveAndClick(targetX, targetY, _getCursorPos, button = 'left') {
    await moveTo(targetX, targetY, _getCursorPos);
    await click(button);
  }

  function getPressedKeyArray() {
    return Array.from(pressedKeyCodes).slice(0, 6);
  }

  async function syncKeyboardState() {
    await connect();
    await sendCommand(
      CMD_SEND_KB_GENERAL_DATA,
      buildKeyboardPacketData(pressedModifierMask, getPressedKeyArray())
    );
  }

  async function keyToggle(key, state) {
    const normalizedState = state === 'down' ? 'down' : 'up';
    const modifierMask = getModifierMask(key);
    const keyCode = getKeyCode(key);

    if (isModifierKey(key)) {
      if (normalizedState === 'down') {
        pressedModifierMask |= modifierMask;
      } else {
        pressedModifierMask &= ~modifierMask;
      }
      await syncKeyboardState();
      return;
    }

    if (!keyCode) {
      throw new Error(`Unsupported CH9329 keyToggle key: ${key}`);
    }

    if (normalizedState === 'down') {
      pressedKeyCodes.add(keyCode);
    } else {
      pressedKeyCodes.delete(keyCode);
    }

    await syncKeyboardState();
  }

  async function keyTap(key, modifiers = []) {
    const keyCode = getKeyCode(key);
    if (!keyCode) {
      throw new Error(`Unsupported CH9329 keyTap key: ${key}`);
    }

    const mask = modifiers.reduce((value, modifier) => value | getModifierMask(modifier), 0);
    await connect();
    await sendCommand(CMD_SEND_KB_GENERAL_DATA, buildKeyboardPacketData(mask, [keyCode]));
    await sleep(50);
    await sendCommand(CMD_SEND_KB_GENERAL_DATA, buildKeyboardPacketData(0, []));
  }

  async function pasteShortcut(platform) {
    const modifier = normalizePlatform(platform) === 'darwin' ? 'command' : 'control';
    await keyTap('v', [modifier]);
    await keyToggle(modifier, 'up');
  }

  return {
    connect,
    disconnect,
    listDevices: listSerialDevices,
    getHealth,
    moveTo,
    click,
    moveAndClick,
    keyTap,
    keyToggle,
    pasteShortcut,
    _debug: {
      sendAbsoluteMove,
      sendRelativeMove
    }
  };
}

